   131→  const [currentIndex, setCurrentIndex] = useState(0);
   132→  const [isPaused, setIsPaused] = useState(false);
   133→
   134→  // Duplicate array for infinite loop effect
   135→  const extendedTestimonials = [...testimonials, ...testimonials, ...testimonials];
   136→  const offset = testimonials.length; // Start from middle set
   137→
   138→  const nextSlide = useCallback(() => {
   139→    setCurrentIndex((prev) => (prev + 1) % testimonials.length);
   140→  }, [testimonials.length]);
   141→
   142→  const prevSlide = useCallback(() => {
   143→    setCurrentIndex((prev) => (prev - 1 + testimonials.length) % testimonials.length);
   144→  }, [testimonials.length]);
   145→
   146→  // Auto-scroll lent (6 secondes)
   147→  useEffect(() => {
   148→    if (isPaused) return;
   149→    const interval = setInterval(nextSlide, 6000);
   150→    return () => clearInterval(interval);
   151→  }, [isPaused, nextSlide]);
   152→
   153→  // Calculate the translateX percentage
   154→  // Each card is ~33.33% width on desktop with gap
   155→  const getTranslateX = () => {
   156→    // We show 3 cards at a time, so each step moves by 1 card width (~33.33%)
   157→    return `calc(-${(currentIndex + offset) * 33.333}% - ${(currentIndex + offset) * 8}px)`;
