   180→              {locale === "fr"
   181→                ? "Retours de mes collaborateurs sur SoundBetter"
   182→                : "Feedback from my collaborators on SoundBetter"}
   183→            </p>
   184→          </div>
   185→
   186→          {/* Navigation Arrows */}
   187→          <div className="flex items-center gap-3 mt-6 md:mt-0">
   188→            <button
   189→              onClick={prevSlide}
   190→              className="w-12 h-12 bg-neo-text text-neo-text-inverse flex items-center justify-center border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text transition-colors"
   191→              aria-label="Previous"
   192→            >
   193→              <ChevronLeft className="w-6 h-6" />
   194→            </button>
   195→            <button
   196→              onClick={nextSlide}
   197→              className="w-12 h-12 bg-neo-text text-neo-text-inverse flex items-center justify-center border-2 border-neo-border hover:bg-neo-accent hover:text-neo-text transition-colors"
   198→              aria-label="Next"
